            <span>v2.4.1</span>
            <span className="w-1 h-1 bg-slate-600 rounded-full" />
            <span className="text-emerald-500">Stable</span>
          </div>
        </div>
      </motion.aside>
    </>
  );
};

export default Sidebar;

