/**
 * Update specific profile fields (whitelisted only).
 * Used from Settings page, onboarding, etc.
 *
 * @param {string} uid
 * @param {Object} updates  — only whitelisted fields are written
 */
export const updateUserProfile = async (uid, updates = {}) => {
