          totalBalance += netChange;
        });

        // Trigger Alert if balance drops between 0.01 and the Threshold
        if (totalBalance > 0 && totalBalance <= lowBalanceThreshold) {
          const todayDate = new Date().toISOString().split('T')[0];
          const uniqueNotifId = `LOW_BAL_${vaultCollection}_${todayDate}`;

          // Push to UI Context
          setVaultAlerts(prev => {
            const filtered = prev.filter(a => a.id !== `low_bal_${vaultCollection}`);
            return [...filtered, {
              id: `low_bal_${vaultCollection}`,
              type: 'CRITICAL ALERT',
              iconType: 'trendDown',
              title: `Low Balance: ${vaultDisplayName}`,
              message: `Your ${vaultDisplayName} balance is critically low (${currencySymbol}${totalBalance.toFixed(2)}). Replenish funds to avoid failures.`,
              actionText: 'View Vault',
              actionLink: linkPath
            }];
          });

          // Push to Firebase Notifications (Silent trigger)
          const notifQ = query(collection(db, "users", user.uid, "notifications"), where("uniqueId", "==", uniqueNotifId));
          const notifSnap = await getDocs(notifQ);

          if (notifSnap.empty) {
            try {
              await addDoc(collection(db, "users", user.uid, "notifications"), {
                uniqueId: uniqueNotifId,
                title: `Low ${vaultDisplayName} Balance! 📉`,
                message: `Available balance dropped to ${currencySymbol}${totalBalance.toFixed(2)}.`,
                type: 'system_alert',
                isRead: false,
                timestamp: new Date().getTime(),
                link: linkPath
              });

              if (speak) speak(`Warning. Your ${vaultDisplayName} balance is running low.`);
            } catch(e) { console.error("JARVIS: Failed to log vault alert"); }
          }
        } else {
          // Remove from J.A.R.V.I.S UI if user adds money above the threshold
          setVaultAlerts(prev => prev.filter(a => a.id !== `low_bal_${vaultCollection}`));
        }

        loadedModules[moduleKey] = true;
        checkLoading();
      });
    };

    // Attach real-time listeners for all 3 Fiat Vaults
    const unsubBank = monitorVault("bankWallet", "Bank Vault", "/dashboard/accounts/bank", "bank");
    const unsubCash = monitorVault("cashWallet", "Physical Cash", "/dashboard/accounts/cash", "cash");
    const unsubOnline = monitorVault("onlineWallet", "Online Wallet", "/dashboard/accounts/online", "online");


    // 🚀 2. STAKING & YIELD MONITOR
    const unsubStaking = onSnapshot(query(collection(db, "users", user.uid, "stakingLogs")), (snapshot) => {
      const stakes = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      const newStakingAlerts = [];
      const today = new Date();
      today.setHours(0,0,0,0); // Normalize today for strict comparison

      stakes.forEach(stake => {
        // Handle Lock/Fixed Staking
        if (stake.lockPeriod && stake.lockPeriod !== 'Flexible') {
          const startDate = new Date(stake.startDate);
          const lockDays = parseInt(stake.lockPeriod);
          const expiryDate = new Date(startDate);
          expiryDate.setDate(expiryDate.getDate() + lockDays);
          expiryDate.setHours(0,0,0,0);

          if (today >= expiryDate) {
            newStakingAlerts.push({
              id: `stake_unlock_${stake.id}`, type: "Yield Alert", title: "Harvest Ready",
              message: `Sir, your ${lockDays} days lock period for ${stake.coin || stake.platform} has ended. Please claim your rewards to avoid losing compound interest.`,
              iconType: "shield", actionText: "Harvest Now", actionLink: '/dashboard/crypto/staking' 
            });
          }
        }

        // Handle LP / Pool / Custom Yield Tracking
        if (stake.earningType === 'pool') {
          const lastClaim = stake.claimedHistory && stake.claimedHistory.length > 0 
            ? new Date(stake.claimedHistory[stake.claimedHistory.length - 1].timestamp) 
            : new Date(stake.startDate);

          const daysSinceLastClaim = Math.floor((today - lastClaim) / (1000 * 60 * 60 * 24));

          if (daysSinceLastClaim > 15) {
             newStakingAlerts.push({
               id: `pool_idle_${stake.id}`, type: "Opportunity", title: "Unclaimed LP Yield",
               message: `You haven't claimed your ${stake.platform} Liquidity Pool yields for over 15 days. Check your dashboard and harvest the tokens.`,
               iconType: "bulb", actionText: "Check Platform", actionLink: '/dashboard/crypto/staking' 
             });
          }
        }
      });
      setStakingAlerts(newStakingAlerts);
      loadedModules.stake = true; checkLoading();
    });


    // 🚀 3. EXPENSE MONITOR
    const highExpenseThreshold = ['USD', 'EUR', 'GBP', 'AUD', 'CAD'].includes(baseCurrency) ? 150 : 7500;
    const unsubExpense = onSnapshot(query(collection(db, "users", user.uid, "expenseLogs"), orderBy("timestamp", "desc"), limit(20)), (snapshot) => {
      const expenses = snapshot.docs.map(doc => doc.data());
      let newExpenseAlerts = [];
      const today = new Date();

      if (expenses.length > 0) {
        // Find if there is any expense within last 3 days matching threshold
        const recentHighExpense = expenses.find(exp => {
          const amt = parseFloat(exp.finalBaseAmount || exp.amount) || 0;
          const expDate = new Date(exp.timestamp || exp.date);
          const daysAgo = (today - expDate) / (1000 * 60 * 60 * 24);
          return amt >= highExpenseThreshold && daysAgo <= 3 && !exp.isVirtualCrypto && !exp.isGoalLock; // Don't flag app-internal syncs
        });

        if (recentHighExpense) {
           const finalAmountVal = parseFloat(recentHighExpense.finalBaseAmount || recentHighExpense.amount);
           const formattedAmount = finalAmountVal.toLocaleString(undefined, {minimumFractionDigits: 0});

           newExpenseAlerts.push({
             id: `high_expense_alert_${recentHighExpense.timestamp || Date.now()}`, type: "Expense Warning", title: "High Recent Expenditure",
             message: `Warning. I detected a high expense of ${currencySymbol}${formattedAmount} in ${recentHighExpense.category || 'Other'}. Please monitor your budget carefully this week.`,
             iconType: "trendDown", actionText: "Review Expenses", actionLink: '/dashboard/expense' 
           });
        }
      }
      setExpenseAlerts(newExpenseAlerts);
      loadedModules.exp = true; checkLoading();
    });


    // 🚀 4. THE BILLS MONITOR 
    const unsubBills = onSnapshot(query(collection(db, "users", user.uid, "billReminders"), where("isPaid", "==", false)), async (snapshot) => {
      const todayDate = new Date().toISOString().split('T')[0];
      const newBillAlerts = [];

      for (const docSnap of snapshot.docs) {
        const bill = docSnap.data();

        if (bill.dueDate && bill.dueDate <= todayDate) {
          const isOverdue = bill.dueDate < todayDate;

          newBillAlerts.push({
            id: `bill_${docSnap.id}`, type: isOverdue ? 'CRITICAL ALERT' : 'REMINDER', iconType: isOverdue ? 'trendDown' : 'bulb',
            title: isOverdue ? `Overdue: ${bill.title}` : `Due Today: ${bill.title}`,
            message: `Your bill for ${bill.title} of amount ${currencySymbol}${bill.amount} is ${isOverdue ? `overdue since ${bill.dueDate}` : 'due today'}. Please settle it to avoid penalties.`,
            actionText: 'Settle Bill Now', actionLink: '/dashboard/alerts/bills' 
          });

          // Database Push Notification
          const uniqueNotifId = `BILL_NOTIF_${docSnap.id}_${todayDate}`;
          const notifQ = query(collection(db, "users", user.uid, "notifications"), where("uniqueId", "==", uniqueNotifId));
          const notifSnap = await getDocs(notifQ);

          if (notifSnap.empty) {
            try {
              await addDoc(collection(db, "users", user.uid, "notifications"), {
                uniqueId: uniqueNotifId, title: isOverdue ? 'Overdue Bill Alert! 🚨' : 'Bill Due Today! ⚠️',
                message: `Your ${bill.title} bill of ${currencySymbol}${bill.amount} is pending.`, type: 'bill_alert', isRead: false,
                timestamp: new Date().getTime(), link: '/dashboard/alerts/bills'
              });

              if (speak) {
                speak(isOverdue ? `Urgent attention. Your ${bill.title} bill is overdue.` : `Attention. Your ${bill.title} bill is due today.`);
              }
            } catch(e) { console.error("JARVIS: Failed to log bill alert"); }
          }
        }
      }
      setBillAlerts(newBillAlerts);
      loadedModules.bill = true; checkLoading();
    });


    // 🚀 5. THE FORMAL LOAN (EMI) MONITOR
    const unsubLoans = onSnapshot(query(collection(db, "users", user.uid, "parties"), where("accountType", "==", "loan"), where("status", "==", "active")), async (snapshot) => {
      const todayDate = new Date().toISOString().split('T')[0];
      const newLoanAlerts = [];

      for (const docSnap of snapshot.docs) {
        const loan = docSnap.data();

        if (loan.emiDueDate && loan.netBalance !== 0 && loan.emiDueDate <= todayDate) {
          const isOverdue = loan.emiDueDate < todayDate;

          newLoanAlerts.push({
            id: `loan_${docSnap.id}`, type: isOverdue ? 'DEBT ALERT' : 'LOAN REMINDER', iconType: isOverdue ? 'trendDown' : 'shield',
            title: isOverdue ? `Overdue EMI: ${loan.name}` : `EMI Due Today: ${loan.name}`,
            message: `Your EMI installment of ${currencySymbol}${loan.emiAmount} for ${loan.name} is ${isOverdue ? `overdue since ${loan.emiDueDate}` : 'due today'}.`,
            actionText: 'Pay EMI Now', actionLink: `/dashboard/parties/${docSnap.id}` 
          });

          const uniqueNotifId = `LOAN_NOTIF_${docSnap.id}_${todayDate}`;
          const notifQ = query(collection(db, "users", user.uid, "notifications"), where("uniqueId", "==", uniqueNotifId));
          const notifSnap = await getDocs(notifQ);

          if (notifSnap.empty) {
            try {
              await addDoc(collection(db, "users", user.uid, "notifications"), {
                uniqueId: uniqueNotifId, title: isOverdue ? 'Overdue EMI Alert! 🚨' : 'EMI Due Today! 🏦',
                message: `Your ${loan.name} EMI of ${currencySymbol}${loan.emiAmount} is pending.`, type: 'loan_alert', isRead: false,
                timestamp: new Date().getTime(), link: `/dashboard/parties/${docSnap.id}`
              });

              if (speak) speak(`Reminder. Your EMI payment for ${loan.name} is ${isOverdue ? 'overdue' : 'due today'}.`);
            } catch(e) { console.error("JARVIS: Failed to log loan alert"); }
          }
        }
      }
      setLoanAlerts(newLoanAlerts);
      loadedModules.loan = true; checkLoading();
    });

    // Timeout failsafe to clear loader
    const loadingTimeout = setTimeout(() => setIsBrainLoading(false), 3000);

    return () => {
      unsubBank(); unsubCash(); unsubOnline(); 
      unsubStaking(); unsubExpense(); unsubBills(); unsubLoans();
      clearTimeout(loadingTimeout);
    };
  }, [user, baseCurrency, currencySymbol, speak]); 

  // 🚀 Combine ALL alerts into one master array (Memoized to prevent unnecessary re-renders)
  const alerts = useMemo(() => {
    return [...vaultAlerts, ...stakingAlerts, ...expenseAlerts, ...billAlerts, ...loanAlerts];
  }, [vaultAlerts, stakingAlerts, expenseAlerts, billAlerts, loanAlerts]);

  return { alerts, isBrainLoading };
};

// src/hooks/useAsyncEffect.js
import { useEffect, useRef, useCallback } from 'react';

export const useAsyncEffect = (asyncFn, dependencies = []) => {
  const isMountedRef = useRef(true);
  const abortControllerRef = useRef(null);

  useEffect(() => {
    isMountedRef.current = true;
    abortControllerRef.current = new AbortController();

    const executeAsync = async () => {
      try {
        await asyncFn(isMountedRef, abortControllerRef.current.signal);
      } catch (error) {
        // Don't log abort errors
        if (error.name === 'AbortError') return;

        if (isMountedRef.current) {
          console.error('Async effect error:', error);
        }
      }
    };

    executeAsync();

    return () => {
      isMountedRef.current = false;
      abortControllerRef.current?.abort(); // ✅ ABORT pending requests
    };
  }, dependencies);

  const safeSetState = useCallback((setState) => {
    if (isMountedRef.current) {
      setState();
    }
  }, []);

  return { safeSetState, isMountedRef };
};

// Usage:
const { safeSetState } = useAsyncEffect(async (isMounted, signal) => {
  const userSnap = await getDoc(doc(db, "users", user.uid), {
    signal // Pass abort signal to Firestore listener
  });

  if (signal.aborted) return; // Check if aborted

  safeSetState(() => {
    setUserData(userSnap.data());
  });
});

// src/hooks/useAuth.js - IMPROVED VERSION

import { useContext } from 'react';
import { AuthContext } from '../context/AuthContext';

/**
 * Custom hook to access Auth context
 * 
 * @returns {Object} Auth context value containing:
 *   - user: Firebase user object or null
 *   - loading: Boolean indicating auth state is loading
 *   - isAdmin: Boolean flag for admin access
 *   - dbData: User profile from Firestore
 *   - baseCurrency: User's selected currency
 *   - formatGlobalDate: Date formatter function
 *   - logout: Function to sign out user
 *   ... and more
 * 
 * @throws {Error} If hook is used outside AuthProvider
 * 
 * @example
 * function MyComponent() {
 *   const { user, logout, baseCurrency } = useAuth();
 *   
 *   if (!user) return <Login />;
 *   
 *   return (
 *     <div>
 *       <p>Currency: {baseCurrency}</p>
 *       <button onClick={logout}>Sign Out</button>
 *     </div>
 *   );
 * }
 */
export const useAuth = () => {
  const context = useContext(AuthContext);

  // ✅ Better error message with helpful debugging info
  if (!context) {
    // Development warning
    if (process.env.NODE_ENV === 'development') {
      console.warn(
        '[useAuth] ⚠️ Hook called outside of <AuthProvider>\n' +
        'Make sure your component tree is wrapped with AuthProvider:\n' +
        '\n' +
        '<AuthProvider>\n' +
        '  <App />\n' +
        '</AuthProvider>'
      );
    }

    throw new Error(
      'useAuth must be used within an <AuthProvider> component. ' +
      'Wrap your app with AuthProvider in main.jsx or the root component.'
    );
  }

  // ✅ Ensure all expected properties exist (safety for refactoring)
  const {
    user = null,
    dbData = null,
    loading = true,
    isAdmin = false,
    avatar = null,
    displayName = 'User',
    baseCurrency = 'USD',
    selectedCryptos = [],
    selectedFiats = [],
    formatGlobalDate,
    getCalendarMonthKey,
    // ... all other properties with safe defaults
    ...rest
  } = context;

  return {
    user,
    dbData,
    loading,
    isAdmin,
    avatar,
    displayName,
    baseCurrency,
    selectedCryptos,
    selectedFiats,
    formatGlobalDate,
    getCalendarMonthKey,
    ...rest
  };
};

// ✅ Add display name for React DevTools
useAuth.displayName = 'useAuth';

// src/hooks/useDashboardData.js
//
// Hardened version with:
// - dispatch guard (prev || {})
// - crypto normalization and holdings calculation
// - safe fallback listener registration (try/catch)
// - error dispatch so UI can show toasts
// - optional limit on crypto snapshot to avoid unbounded reads
//
// Usage: useDashboardData(user, setDashData)

import { useEffect, useRef, useCallback } from 'react';
import {
  collection,
  doc,
  onSnapshot,
  query,
  orderBy,
  limit as firestoreLimit,
} from 'firebase/firestore';
import { db } from '../firebase/firebaseConfig';
import { calcVaultBalance } from '../utils/balanceEngine';
import {
  safeParseFloat,
  safeAdd,
  safeSum,
} from '../utils/safeMath';

export const useDashboardData = (user, onDataUpdate, options = {}) => {
  // options: { cryptoLimit: number | null } - pass null to disable limit
  const { cryptoLimit = 2000 } = options;

  const unsubscribersRef = useRef([]);

  // Stabilize callback so it doesn't appear in deps
  const callbackRef = useRef(onDataUpdate);
  useEffect(() => { callbackRef.current = onDataUpdate; }, [onDataUpdate]);

  // Stable dispatcher
  const dispatch = useCallback((updater) => {
    try {
      callbackRef.current?.(updater);
    } catch (e) {
      // swallow to avoid breaking listeners; log for debugging
      // eslint-disable-next-line no-console
      console.error('[useDashboardData] dispatch error:', e);
    }
  }, []);

  // Helper to register unsubscribers immediately
  const register = (unsub) => {
    if (typeof unsub === 'function') {
      unsubscribersRef.current.push(unsub);
    }
  };

  useEffect(() => {
    // Cleanup any previous listeners if user missing
    if (!user?.uid) {
      unsubscribersRef.current.forEach(fn => {
        try { fn?.(); } catch (e) { console.error('[Dashboard] cleanup error', e); }
      });
      unsubscribersRef.current = [];
      return;
    }

    const uid = user.uid;

    // Ensure previous listeners cleared before registering new ones
    unsubscribersRef.current.forEach(fn => {
      try { fn?.(); } catch (e) { console.error('[Dashboard] cleanup error', e); }
    });
    unsubscribersRef.current = [];

    // ── 1. Bank Wallet summary (single doc)
    try {
      const unsubBank = onSnapshot(
        doc(db, 'users', uid, 'walletSummary', 'bank'),
        snap => {
          const data = snap.exists() ? snap.data() : {};
          dispatch(prev => ({
            ...(prev || {}),
            bankTotal: safeParseFloat(data.totalBalance, 0),
            bankIncome: safeParseFloat(data.totalIncome, 0),
            bankExpense: safeParseFloat(data.totalExpense, 0),
          }));
        },
        err => {
          console.error('[Dashboard] Bank summary error:', err);
          dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(err) }));
          // fallback: try registering collection snapshot safely
          try {
            const unsubFallback = onSnapshot(
              collection(db, 'users', uid, 'bankWallet'),
              snap => {
                const txs = snap.docs.map(d => d.data());
                const { balance } = calcVaultBalance(txs);
                dispatch(prev => ({ ...(prev || {}), bankTotal: balance }));
              }
            );
            register(unsubFallback);
          } catch (e) {
            console.error('[Dashboard] Bank fallback listener failed to register', e);
          }
        }
      );
      register(unsubBank);
    } catch (e) {
      console.error('[Dashboard] Failed to register bank listener', e);
      dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(e) }));
    }

    // ── 2. Cash Wallet summary
    try {
      const unsubCash = onSnapshot(
        doc(db, 'users', uid, 'walletSummary', 'cash'),
        snap => {
          const data = snap.exists() ? snap.data() : {};
          dispatch(prev => ({
            ...(prev || {}),
            cashTotal: safeParseFloat(data.totalBalance, 0),
            cashIncome: safeParseFloat(data.totalIncome, 0),
            cashExpense: safeParseFloat(data.totalExpense, 0),
          }));
        },
        err => {
          console.error('[Dashboard] Cash summary error:', err);
          dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(err) }));
          try {
            const unsubFallback = onSnapshot(
              collection(db, 'users', uid, 'cashWallet'),
              snap => {
                const txs = snap.docs.map(d => d.data());
                dispatch(prev => ({ ...(prev || {}), cashTotal: calcVaultBalance(txs).balance }));
              }
            );
            register(unsubFallback);
          } catch (e) {
            console.error('[Dashboard] Cash fallback listener failed to register', e);
          }
        }
      );
      register(unsubCash);
    } catch (e) {
      console.error('[Dashboard] Failed to register cash listener', e);
      dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(e) }));
    }

    // ── 3. Online Wallet summary
    try {
      const unsubOnline = onSnapshot(
        doc(db, 'users', uid, 'walletSummary', 'online'),
        snap => {
          const data = snap.exists() ? snap.data() : {};
          dispatch(prev => ({
            ...(prev || {}),
            onlineTotal: safeParseFloat(data.totalBalance, 0),
            onlineIncome: safeParseFloat(data.totalIncome, 0),
            onlineExpense: safeParseFloat(data.totalExpense, 0),
          }));
        },
        err => {
          console.error('[Dashboard] Online summary error:', err);
          dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(err) }));
          try {
            const unsubFallback = onSnapshot(
              collection(db, 'users', uid, 'onlineWallet'),
              snap => {
                const txs = snap.docs.map(d => d.data());
                dispatch(prev => ({ ...(prev || {}), onlineTotal: calcVaultBalance(txs).balance }));
              }
            );
            register(unsubFallback);
          } catch (e) {
            console.error('[Dashboard] Online fallback listener failed to register', e);
          }
        }
      );
      register(unsubOnline);
    } catch (e) {
      console.error('[Dashboard] Failed to register online listener', e);
      dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(e) }));
    }

    // ── 4. Crypto Wallet logs (full collection needed for holdings)
    try {
      const cryptoCol = collection(db, 'users', uid, 'cryptoWalletLogs');
      const cryptoQuery = cryptoLimit && Number.isFinite(cryptoLimit)
        ? query(cryptoCol, orderBy('timestamp', 'desc'), firestoreLimit(cryptoLimit))
        : query(cryptoCol, orderBy('timestamp', 'desc'));

      const unsubCrypto = onSnapshot(
        cryptoQuery,
        snap => {
          try {
            const cryptoTransactions = snap.docs.map(d => ({ id: d.id, ...d.data() }));

            // calculate crypto total using balance engine
            const { balance: cryptoTotal } = calcVaultBalance(cryptoTransactions);

            // build holdings map with normalized signs and fields
            const holdingsMap = {};
            cryptoTransactions.forEach(tx => {
              const coin = (tx.coin || tx.symbol || 'UNKNOWN').toUpperCase();
              const rawAmount = tx.finalBaseAmount ?? tx.amount ?? tx.quantity ?? 0;
              let amount = safeParseFloat(rawAmount, 0);
              const type = (tx.type || '').toLowerCase();

              // normalize sign by type
              if (['sell', 'withdraw', 'swap_out', 'bridge_out', 'out', 'debit'].includes(type)) {
                amount = -Math.abs(amount);
              } else if (['buy', 'in', 'earn', 'stake_reward', 'unstake', 'swap_in', 'bridge_in'].includes(type)) {
                amount = Math.abs(amount);
              } // else leave as-is

              if (!holdingsMap[coin]) {
                holdingsMap[coin] = { coin, quantity: 0, totalCost: 0 };
              }

              holdingsMap[coin].quantity = safeAdd(holdingsMap[coin].quantity, amount);

              // update cost basis only for buy/in with usdValue or costBasis
              const usdVal = safeParseFloat(tx.usdValue ?? tx.costBasis ?? 0, 0);
              if (usdVal > 0 && ['buy', 'in'].includes(type)) {
                holdingsMap[coin].totalCost = safeAdd(holdingsMap[coin].totalCost, usdVal);
              }
            });

            const cryptoHoldings = Object.values(holdingsMap).filter(h => h.quantity > 0);

            dispatch(prev => ({
              ...(prev || {}),
              cryptoTransactions,
              cryptoHoldings,
              cryptoTotal,
            }));
          } catch (error) {
            console.error('[Dashboard] Crypto calc error:', error);
            dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(error) }));
          }
        },
        err => {
          console.error('[Dashboard] Crypto listener error:', err);
          dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(err) }));
        }
      );
      register(unsubCrypto);
    } catch (e) {
      console.error('[Dashboard] Failed to register crypto listener', e);
      dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(e) }));
    }

    // ── 5. Income Logs
    try {
      const unsubIncome = onSnapshot(
        query(
          collection(db, 'users', uid, 'incomeLogs'),
          orderBy('timestamp', 'desc')
        ),
        snap => {
          try {
            const rawIncomes = snap.docs.map(d => ({ id: d.id, ...d.data() }));
            const incomeTotal = safeSum(
              rawIncomes,
              d => safeParseFloat(d.finalBaseAmount ?? d.amount, 0)
            );
            dispatch(prev => ({ ...(prev || {}), rawIncomes, incomeTotal }));
          } catch (error) {
            console.error('[Dashboard] Income calc error:', error);
            dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(error) }));
          }
        },
        err => {
          console.error('[Dashboard] Income listener error:', err);
          dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(err) }));
        }
      );
      register(unsubIncome);
    } catch (e) {
      console.error('[Dashboard] Failed to register income listener', e);
      dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(e) }));
    }

    // ── 6. Expense Logs
    try {
      const unsubExpense = onSnapshot(
        query(
          collection(db, 'users', uid, 'expenseLogs'),
          orderBy('timestamp', 'desc')
        ),
        snap => {
          try {
            const rawExpenses = snap.docs.map(d => ({ id: d.id, ...d.data() }));
            const expenseTotal = safeSum(
              rawExpenses,
              d => safeParseFloat(d.finalBaseAmount ?? d.amount, 0)
            );
            dispatch(prev => ({ ...(prev || {}), rawExpenses, expenseTotal }));
          } catch (error) {
            console.error('[Dashboard] Expense calc error:', error);
            dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(error) }));
          }
        },
        err => {
          console.error('[Dashboard] Expense listener error:', err);
          dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(err) }));
        }
      );
      register(unsubExpense);
    } catch (e) {
      console.error('[Dashboard] Failed to register expense listener', e);
      dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(e) }));
    }

    // ── 7. Parties (Khata / Party Ledger)
    try {
      const unsubParties = onSnapshot(
        collection(db, 'users', uid, 'parties'),
        snap => {
          try {
            let khataReceivables = 0;
            let khataPayables = 0;

            snap.docs.forEach(d => {
              const data = d.data();
              if (data.status === 'bad_debt') return;

              const net = safeParseFloat(data.netBalance, 0);
              if (net > 0) {
                khataReceivables = safeAdd(khataReceivables, net);
              } else if (net < 0) {
                khataPayables = safeAdd(khataPayables, Math.abs(net));
              }
            });

            dispatch(prev => ({ ...(prev || {}), khataReceivables, khataPayables }));
          } catch (error) {
            console.error('[Dashboard] Parties calc error:', error);
            dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(error) }));
          }
        },
        err => {
          console.error('[Dashboard] Parties listener error:', err);
          dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(err) }));
        }
      );
      register(unsubParties);
    } catch (e) {
      console.error('[Dashboard] Failed to register parties listener', e);
      dispatch(prev => ({ ...(prev || {}), dashboardError: true, lastError: String(e) }));
    }

    // Cleanup on unmount or user change
    return () => {
      unsubscribersRef.current.forEach(fn => {
        try { fn?.(); } catch (e) { console.error('[Dashboard] Cleanup error:', e); }
      });
      unsubscribersRef.current = [];
    };
  }, [user?.uid, dispatch, cryptoLimit]);

  return {
    cleanup: () => {
      unsubscribersRef.current.forEach(fn => {
        try { fn?.(); } catch (e) { console.error('[Dashboard] manual cleanup error:', e); }
      });
      unsubscribersRef.current = [];
    },
  };
};

// src/hooks/usePaginatedLogs.js
import { useState, useEffect, useCallback } from 'react';
import { collection, query, orderBy, limit, startAfter, getDocs } from 'firebase/firestore';
import { db } from '../firebase/firebaseConfig';

/**
 * @param {string} uid – current user UID
 * @param {string} subCollection – e.g. 'expenseLogs'
 * @param {number} pageSize – documents per page (default 20)
 * @param {boolean} enabled – only fetch when true
 * @returns {{ logs, loading, error, hasMore, loadMore, refresh, isPaginating }}
 */
export function usePaginatedLogs(uid, subCollection, pageSize = 20, enabled = true) {
  const [logs, setLogs] = useState([]);
  const [lastDoc, setLastDoc] = useState(null);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [isPaginating, setIsPaginating] = useState(false); // ✅ NEW: Prevent multiple concurrent loads
  const [error, setError] = useState(null);

  // ✅ FIX 1: Memoize collectionRef separately to prevent infinite loops
  // Use useCallback to ensure it's stable across renders
  const getCollectionRef = useCallback(() => {
    return collection(db, 'users', uid, subCollection);
  }, [uid, subCollection]);

  // ✅ FIX 2: Separate initial load logic
  const fetchInitial = useCallback(async () => {
    if (!uid || !enabled) return;
    setLoading(true);
    setError(null);
    setLogs([]);
    setLastDoc(null);

    try {
      const collectionRef = getCollectionRef();
      const q = query(collectionRef, orderBy('timestamp', 'desc'), limit(pageSize));
      const snap = await getDocs(q);

      const docs = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setLogs(docs);
      setLastDoc(snap.docs[snap.docs.length - 1] || null);
      setHasMore(snap.docs.length === pageSize);
    } catch (err) {
      console.error('Pagination fetch error:', err);
      setError(err.message);
      setHasMore(false);
    } finally {
      setLoading(false);
    }
  }, [uid, enabled, pageSize, getCollectionRef]);

    // Optional: Add validation
if (!subCollection || typeof subCollection !== 'string') {
  setError('Invalid subCollection');
  return;
}

// Optional: Handle empty explicitly
if (snap.empty) {
  setHasMore(false);
}

// Optional: Better error messages
setError(`Load more failed: ${err.message}`);
  // ✅ FIX 3: Separate load more logic with isPaginating guard
  const loadMore = useCallback(async () => {
    // ✅ Check isPaginating to prevent concurrent requests
    if (!lastDoc || !hasMore || loading || isPaginating) return;

    setIsPaginating(true); // ✅ Set this FIRST
    try {
      const collectionRef = getCollectionRef();
      const q = query(
        collectionRef,
        orderBy('timestamp', 'desc'),
        startAfter(lastDoc),
        limit(pageSize)
      );
      const snap = await getDocs(q);
      const newDocs = snap.docs.map(d => ({ id: d.id, ...d.data() }));

      setLogs(prev => [...prev, ...newDocs]);
      const newLast = snap.docs[snap.docs.length - 1] || null;
      setLastDoc(newLast);
      setHasMore(snap.docs.length === pageSize);
    } catch (err) {
      console.error('Load more error:', err);
      setError(err.message);
    } finally {
      setIsPaginating(false); // ✅ Always reset this
    }
  }, [lastDoc, hasMore, loading, isPaginating, pageSize, getCollectionRef]);

  // ✅ FIX 4: Refresh with proper cleanup
  const refresh = useCallback(() => {
    setLogs([]);
    setLastDoc(null);
    setHasMore(true);
    setError(null);
    fetchInitial();
  }, [fetchInitial]);

  // ✅ FIX 5: Clean dependency array
  useEffect(() => {
    fetchInitial();
  }, [uid, subCollection, pageSize, enabled]); // ✅ Direct deps, not fetchInitial

  return {
    logs,
    loading,
    isPaginating, // ✅ EXPORT this for UI to check
    error,
    hasMore,
    loadMore,
    refresh
  };
}

/**
 * PAGINATED MONTHLY LOGS HOOK - IMPROVED VERSION
 * =============================================
 * 
 * Displays transaction logs grouped by month with pagination.
 * Fetches ALL records once, then paginates for display.
 * 
 * ✅ FIXED VERSION — 3 critical bugs patched:
 *   Bug 1: calculateAllBalances now accumulates cumulative total correctly
 *   Bug 2: limit(500) removed — fetches ALL records
 *   Bug 3: loadMonthsBatch receives fresh data, avoiding stale closures
 * 
 * ✅ IMPROVEMENTS IN THIS VERSION:
 *   + Error state returned to component
 *   + getCalendarMonthKey validation
 *   + Always reset loading state
 *   + Better error messages
 * 
 * Architecture:
 *   • allRecords  → fetched ONCE (no limit), used ONLY for balance math
 *   • months[]    → display state, paginated by monthsPerPage
 *   • summary     → { totalBalance, totalIncome, totalExpense } always correct
 * 
 * @param {string} userId - Firebase user ID
 * @param {string} subCollection - Collection name (e.g., 'bankLogs', 'incomeLogs')
 * @param {number} [transactionsPerMonth=15] - Initial transactions shown per month
 * @param {number} [monthsPerPage=3] - Months loaded per "Load More"
 * @param {boolean} [enabled=true] - Enable/disable the listener
 * @param {Function} getCalendarMonthKey - Function to extract month key from date
 * @returns {Object} {
 *   months: Array<Month>,
 *   allRecords: Array<Record>,
 *   summary: { totalBalance, totalIncome, totalExpense },
 *   loading: boolean,
 *   error: string|null,
 *   isPaginating: boolean,
 *   hasMore: boolean,
 *   loadMore: Function,
 *   expandMonth: Function,
 *   refresh: Function
 * }
 * 
 * @example
 * const {
 *   months,
 *   summary,
 *   loading,
 *   error,
 *   loadMore,
 *   hasMore,
 *   expandMonth,
 * } = usePaginatedMonthlyLogs(
 *   uid,
 *   'bankLogs',
 *   15,
 *   3,
 *   true,
 *   getCalendarMonthKey
 * );
 * 
 * if (loading) return <Spinner />;
 * if (error) return <Error message={error} />;
 * 
 * return (
 *   <div>
 *     <BalanceBadge value={summary.totalBalance} />
 *     {months.map(month => <MonthSection key={month.monthKey} month={month} />)}
 *     {hasMore && <button onClick={loadMore}>Load More</button>}
 *   </div>
 * );
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { collection, query, orderBy, getDocs } from 'firebase/firestore';
import { db } from '../firebase/firebaseConfig';
import { safeParseFloat, safeAdd, safeSubtract } from '../utils/safeMath';

export function usePaginatedMonthlyLogs(
  userId,
  subCollection,
  transactionsPerMonth = 15,
  monthsPerPage = 3,
  enabled = true,
  getCalendarMonthKey = null
) {
  // ═══════════════════════════════════════════════════════════════════════
  // STATE
  // ═══════════════════════════════════════════════════════════════════════

  const [months, setMonths] = useState([]);
  const [allRecords, setAllRecords] = useState([]);
  const [monthKeys, setMonthKeys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null); // ✅ NEW: Error state
  const [isPaginating, setIsPaginating] = useState(false);
  const [hasMore, setHasMore] = useState(false);

  // ✅ Summary is ALWAYS derived from complete allRecords,
  // never from paginated display slice
  const [summary, setSummary] = useState({
    totalBalance: 0,
    totalIncome: 0,
    totalExpense: 0,
  });

  // ✅ Use refs to avoid dependency issues
  const loadedMonthIndicesRef = useRef(new Set());
  const nextPageStartIndexRef = useRef(0);

  // ═══════════════════════════════════════════════════════════════════════
  // HELPERS
  // ═══════════════════════════════════════════════════════════════════════

  /**
   * ✅ BUG #1 FIX - Calculates balances by iterating EVERY monthKey
   * in chronological order, accumulating the running total continuously.
   * 
   * @param {Object} monthsMap - Map to update with balance values
   * @param {Array<string>} allKeys - All month keys in query order
   * @param {Array<Object>} records - All transaction records
   * @returns {Object} { totalBalance, totalIncome, totalExpense }
   */
  const calculateAllBalances = useCallback(
    (monthsMap, allKeys, records) => {
      if (!Array.isArray(records) || records.length === 0) {
        return { totalBalance: 0, totalIncome: 0, totalExpense: 0 };
      }

      const sortedKeys = [...allKeys].reverse(); // oldest → newest
      let cumulativeBalance = 0;
      let totalIncome = 0;
      let totalExpense = 0;

      sortedKeys.forEach(monthKey => {
        const monthRecords = records.filter(
          r => getCalendarMonthKey(r.date || r.timestamp) === monthKey
        );

        let inflow = 0;
        let outflow = 0;

        monthRecords.forEach(rec => {
          try {
            const amount = safeParseFloat(rec.finalBaseAmount ?? rec.amount);
            const type = (rec.type || rec.logType || '').toLowerCase();

            if (type === 'in' || type === 'income') {
              inflow = safeAdd(inflow, amount);
              totalIncome = safeAdd(totalIncome, amount);
            } else if (
              type === 'out' ||
              type === 'expense' ||
              type === 'debit'
            ) {
              outflow = safeAdd(outflow, amount);
              totalExpense = safeAdd(totalExpense, amount);
            }
          } catch (err) {
            console.warn('[calculateAllBalances] Error processing record:', rec, err);
          }
        });

        const opening = cumulativeBalance;
        // ✅ BUG #1 FIX: Accumulate ALWAYS — never skip
        const closing = safeSubtract(safeAdd(opening, inflow), outflow);
        cumulativeBalance = closing;

        // Only update display months that are currently shown
        if (monthsMap[monthKey]) {
          monthsMap[monthKey].openingBalance = opening;
          monthsMap[monthKey].closingBalance = closing;
          monthsMap[monthKey].monthInflow = inflow;
          monthsMap[monthKey].monthOutflow = outflow;
        }
      });

      return { totalBalance: cumulativeBalance, totalIncome, totalExpense };
    },
    [getCalendarMonthKey]
  );

  /**
   * Build display months for a batch of indices.
   * 
   * ✅ BUG #3 FIX - Accepts explicit `keys` and `records` arguments
   * so it always uses fresh data, not stale closure values.
   * 
   * @param {number} startIndex - Starting month index
   * @param {Array<string>} keys - All month keys
   * @param {Array<Object>} records - All records
   */
  const buildMonthsBatch = useCallback(
    (startIndex, keys, records) => {
      if (!keys.length || !getCalendarMonthKey) {
        console.warn('[buildMonthsBatch] Missing keys or getCalendarMonthKey');
        return;
      }

      const indicesToLoad = [];
      for (
        let i = startIndex;
        i < startIndex + monthsPerPage && i < keys.length;
        i++
      ) {
        if (!loadedMonthIndicesRef.current.has(i)) {
          indicesToLoad.push(i);
        }
      }

      if (!indicesToLoad.length) {
        // All months already loaded in this batch
        return;
      }

      try {
        // Build display slices for newly loaded months
        const newMonthsMap = {};
        indicesToLoad.forEach(idx => {
          const monthKey = keys[idx];
          const allMonthRecs = records.filter(
            r => getCalendarMonthKey(r.date || r.timestamp) === monthKey
          );

          newMonthsMap[monthKey] = {
            monthKey,
            displayName: formatMonthName(monthKey, allMonthRecs[0]?.date),
            records: allMonthRecs.slice(0, transactionsPerMonth),
            totalRecordsInMonth: allMonthRecs.length,
            hasMoreInMonth: allMonthRecs.length > transactionsPerMonth,
            isExpanded: false,
            openingBalance: 0,
            closingBalance: 0,
            monthInflow: 0,
            monthOutflow: 0,
          };
        });

        // ✅ BUG #1 FIX: calculateAllBalances iterates ALL keys
        // so every month gets correct running cumulative total
        const totals = calculateAllBalances(newMonthsMap, keys, records);

        // Update summary (source of truth for balance badges)
        setSummary(totals);

        // Merge into display list
        setMonths(prev => {
          const updated = [...prev];
          Object.values(newMonthsMap).forEach(newMonth => {
            const idx = updated.findIndex(m => m.monthKey === newMonth.monthKey);
            if (idx >= 0) updated[idx] = newMonth;
            else updated.push(newMonth);
          });
          return updated.sort(
            (a, b) => keys.indexOf(a.monthKey) - keys.indexOf(b.monthKey)
          );
        });

        indicesToLoad.forEach(i => loadedMonthIndicesRef.current.add(i));
      } catch (err) {
        console.error('[buildMonthsBatch] Error:', err);
        setError('Error loading transaction data: ' + err.message);
      }
    },
    [calculateAllBalances, getCalendarMonthKey, monthsPerPage, transactionsPerMonth]
  );

  // ═══════════════════════════════════════════════════════════════════════
  // STEP 1 - Fetch ALL records, discover month keys
  // ═══════════════════════════════════════════════════════════════════════

  const discoverMonths = useCallback(async () => {
    if (!userId || !enabled) {
      setLoading(false);
      return;
    }

    // ✅ NEW: Validate getCalendarMonthKey
    if (!getCalendarMonthKey || typeof getCalendarMonthKey !== 'function') {
      console.error('[usePaginatedMonthlyLogs] getCalendarMonthKey must be a function');
      setError('Configuration error: getCalendarMonthKey not provided');
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null); // ✅ Clear previous errors

    try {
      const collRef = collection(db, 'users', String(userId), subCollection);

      // ✅ BUG #2 FIX: Removed limit(500) — fetch ALL records.
      // For 10,000+ records, consider useWalletSummary instead.
      const q = query(collRef, orderBy('timestamp', 'desc'));
      const snap = await getDocs(q);
      const records = snap.docs.map(d => ({ id: d.id, ...d.data() }));

      // Discover unique month keys (newest → oldest)
      const seen = new Set();
      const keys = [];
      records.forEach(rec => {
        try {
          const mk = getCalendarMonthKey(rec.date || rec.timestamp);
          if (mk && !seen.has(mk)) {
            seen.add(mk);
            keys.push(mk);
          }
        } catch (err) {
          console.warn('[usePaginatedMonthlyLogs] Error extracting month key:', err);
        }
      });

      // Reset pagination state
      loadedMonthIndicesRef.current = new Set();
      nextPageStartIndexRef.current = 0;

      setAllRecords(records);
      setMonthKeys(keys);
      setMonths([]);
      setError(null); // ✅ Success: clear error

      // Compute summary over FULL dataset right away
      if (keys.length) {
        const fullMap = {}; // Empty — calculateAllBalances still iterates all
        const totals = calculateAllBalances(fullMap, keys, records);
        setSummary(totals);

        // Load first batch
        buildMonthsBatch(0, keys, records);
        setHasMore(keys.length > monthsPerPage);
      } else {
        setSummary({ totalBalance: 0, totalIncome: 0, totalExpense: 0 });
      }
    } catch (err) {
      console.error('[usePaginatedMonthlyLogs] discoverMonths error:', err);
      // ✅ NEW: Set error state
      setError(`Failed to load transactions: ${err.message}`);
      setMonths([]);
      setAllRecords([]);
      setMonthKeys([]);
      setSummary({ totalBalance: 0, totalIncome: 0, totalExpense: 0 });
    } finally {
      // ✅ ALWAYS reset loading
      setLoading(false);
    }
  }, [
    userId,
    enabled,
    subCollection,
    getCalendarMonthKey,
    monthsPerPage,
    calculateAllBalances,
    buildMonthsBatch,
  ]);

  // ═══════════════════════════════════════════════════════════════════════
  // STEP 2 - Load More (next batch of months)
  // ═══════════════════════════════════════════════════════════════════════

  const loadMore = useCallback(() => {
    if (!hasMore || isPaginating) return;
    setIsPaginating(true);

    // Use rAF so spinner renders before heavy JS work
    requestAnimationFrame(() => {
      const nextIndex = nextPageStartIndexRef.current + monthsPerPage;

      // ✅ BUG #3 FIX: Pass monthKeys + allRecords directly
      // Avoids stale closure issue
      buildMonthsBatch(nextIndex, monthKeys, allRecords);

      nextPageStartIndexRef.current = nextIndex;
      setHasMore(nextIndex + monthsPerPage < monthKeys.length);
      setIsPaginating(false);
    });
  }, [
    hasMore,
    isPaginating,
    monthsPerPage,
    monthKeys,
    allRecords,
    buildMonthsBatch,
  ]);

  // ═══════════════════════════════════════════════════════════════════════
  // STEP 3 - Expand month (show all transactions for that month)
  // ═══════════════════════════════════════════════════════════════════════

  const expandMonth = useCallback(
    monthKey => {
      setMonths(prev =>
        prev.map(m => {
          if (m.monthKey !== monthKey) return m;
          try {
            const full = allRecords.filter(
              r => getCalendarMonthKey(r.date || r.timestamp) === monthKey
            );
            return {
              ...m,
              records: full,
              isExpanded: true,
              hasMoreInMonth: false,
            };
          } catch (err) {
            console.error('[expandMonth] Error:', err);
            setError('Error expanding month: ' + err.message);
            return m;
          }
        })
      );
    },
    [allRecords, getCalendarMonthKey]
  );

  // ═══════════════════════════════════════════════════════════════════════
  // STEP 4 - Refresh
  // ═══════════════════════════════════════════════════════════════════════

  const refresh = useCallback(() => {
    setMonths([]);
    setAllRecords([]);
    setMonthKeys([]);
    setError(null); // ✅ Clear error on refresh
    setSummary({ totalBalance: 0, totalIncome: 0, totalExpense: 0 });
    loadedMonthIndicesRef.current = new Set();
    nextPageStartIndexRef.current = 0;
    discoverMonths();
  }, [discoverMonths]);

  // ═══════════════════════════════════════════════════════════════════════
  // MOUNT / DEPENDENCY CHANGE
  // ═══════════════════════════════════════════════════════════════════════

  useEffect(() => {
    if (enabled && userId) {
      discoverMonths();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [userId, subCollection, enabled]);
  //   ☝️ Intentionally NOT including discoverMonths to avoid refetch on
  //      every render. discoverMonths is recreated when its deps change,
  //      which would cause an infinite loop if listed here.

  // ═══════════════════════════════════════════════════════════════════════
  // RETURN
  // ═══════════════════════════════════════════════════════════════════════

  return {
    months,          // display list (paginated)
    allRecords,      // full dataset (for advanced use)
    summary,         // ✅ ALWAYS CORRECT — use for balance badges!
    loading,
    error,           // ✅ NEW: Error state for UI display
    isPaginating,
    hasMore,
    loadMore,
    expandMonth,
    refresh,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// HELPERS
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Format month key into readable month name
 */
function formatMonthName(monthKey, dateStr) {
  try {
    if (!dateStr) return monthKey;
    return new Date(dateStr).toLocaleString('default', {
      month: 'long',
      year: 'numeric',
    });
  } catch {
    return monthKey;
  }
}

/*
 * ─────────────────────────────────────────────────────────────────────────────
 * USAGE IN WALLET PAGES
 * ─────────────────────────────────────────────────────────────────────────────
 *
 * function WalletPage() {
 *   const {
 *     months,
 *     summary,
 *     loading,
 *     error,         // ✅ NEW: Handle errors
 *     isPaginating,
 *     hasMore,
 *     loadMore,
 *     expandMonth,
 *     refresh,
 *   } = usePaginatedMonthlyLogs(
 *     uid,
 *     'bankLogs',
 *     15,   // transactions per month shown initially
 *     3,    // months per page
 *     true,
 *     getCalendarMonthKey
 *   );
 *
 *   if (loading) return <Spinner />;
 *   
 *   // ✅ NEW: Handle error state
 *   if (error) {
 *     return (
 *       <div className="error">
 *         <p>{error}</p>
 *         <button onClick={refresh}>Retry</button>
 *       </div>
 *     );
 *   }
 *
 *   return (
 *     <div>
 *       {/* ✅ CORRECT — use summary for balance badge */}
 *       <BalanceBadge value={summary.totalBalance} />
 *
 *       {/* Display months */}
 *       {months.map(month => (
 *         <MonthSection
 *           key={month.monthKey}
 *           month={month}
 *           onExpand={() => expandMonth(month.monthKey)}
 *         />
 *       ))}
 *
 *       {/* Load More */}
 *       {hasMore && (
 *         <button onClick={loadMore} disabled={isPaginating}>
 *           {isPaginating ? 'Loading...' : 'Load More'}
 *         </button>
 *       )}
 *     </div>
 *   );
 * }
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * NOTE FOR VERY LARGE COLLECTIONS (10,000+ records)
 * ─────────────────────────────────────────────────────────────────────────────
 * If your collection grows beyond ~5,000 documents, replace the full-fetch
 * with a Firestore summary document pattern:
 *
 *   users/{uid}/walletSummary/bank → { totalBalance, totalIncome, totalExpense }
 *
 * Update it with a Firestore transaction on every add / edit / delete.
 * Then read it via onSnapshot for real-time balance display, and keep
 * usePaginatedMonthlyLogs only for the transaction list UI.
 *
 * See: useWalletSummary.js (companion hook) for the implementation.
 * ─────────────────────────────────────────────────────────────────────────────
 */

export default usePaginatedMonthlyLogs;

