                  <h3 className={`font-black text-sm sm:text-base tracking-tight mb-0.5 w-full text-center truncate px-1 ${isSelected ? 'text-blue-600 dark:text-blue-400' : 'text-slate-800 dark:text-slate-100'}`}>{coin.symbol}</h3>
