const StatBadge = ({ icon: Icon, label, value, color, bgColor, borderColor }) => (
  <div className={`flex items-center gap-3 p-3 sm:p-4 rounded-2xl ${bgColor} border ${borderColor} backdrop-blur-sm`}>
