        <style>{`@keyframes scrollTicker { 0% { transform: translateX(100%); } 100% { transform: translateX(-100%); } } .animate-ticker-scroll { display: inline-flex; white-space: nowrap; animation: scrollTicker 45s linear infinite; } .animate-ticker-scroll:hover { animation-play-state: paused; }`}</style>

        {/* Premium Header */}
        <div className="relative overflow-hidden rounded-[2.5rem] bg-gradient-to-br from-blue-700 via-indigo-700 to-blue-800 p-6 sm:p-8 lg:p-10 shadow-2xl border border-blue-400/30">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,rgba(59,130,246,0.15),transparent_70%)]" />
          <div className="absolute right-0 top-0 w-64 h-64 bg-blue-400/20 rounded-full blur-3xl pointer-events-none" />
          <div className="relative z-10 flex flex-col lg:flex-row lg:items-end justify-between gap-6">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 sm:w-16 sm:h-16 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-[1.5rem] sm:rounded-[2rem] flex items-center justify-center shadow-lg shadow-blue-500/20 shrink-0">
                <FaUniversity size={28} className="text-white" />
              </div>
              <div>
                <h1 className="text-2xl sm:text-3xl lg:text-4xl font-black text-white tracking-tight">Bank Vault</h1>
                <p className="text-xs sm:text-sm font-medium text-blue-100 mt-1">Manage institutional assets and deposits</p>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
              <div className="relative flex-1 lg:flex-none">
                <button onClick={() => !isGeneratingReport && setIsExportMenuOpen(!isExportMenuOpen)} onBlur={() => setTimeout(() => setIsExportMenuOpen(false), 200)} disabled={isGeneratingReport} className="w-full flex items-center justify-center gap-2 px-5 py-3.5 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-black text-xs uppercase tracking-widest backdrop-blur-sm transition-all border border-white/10 active:scale-95 shadow-sm disabled:opacity-50">
                  {isGeneratingReport ? <><HiOutlineRefresh className="animate-spin" size={18} /> Generating...</> : <><HiOutlineDownload size={18} /> Export</>}
                </button>
                {isExportMenuOpen && !isGeneratingReport && (
                  <div className="absolute top-[110%] right-0 w-full lg:w-48 bg-slate-800 border border-slate-700 rounded-2xl shadow-xl flex flex-col p-1.5 z-50 animate-in fade-in zoom-in-95">
                    <button onClick={() => handleDownloadReport('pdf')} className="flex items-center gap-2.5 px-4 py-3 hover:bg-slate-700 text-slate-200 text-[11px] font-black rounded-xl transition-colors"><HiOutlineDocumentText className="text-rose-400" size={18} /> PDF Document</button>
                    <button onClick={() => handleDownloadReport('excel')} className="flex items-center gap-2.5 px-4 py-3 hover:bg-slate-700 text-slate-200 text-[11px] font-black rounded-xl transition-colors"><HiOutlineTable className="text-emerald-400" size={18} /> Excel (CSV)</button>
                  </div>
                )}
              </div>
              <button onClick={openModal} className="flex-1 lg:flex-none flex items-center justify-center gap-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white px-6 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-lg shadow-blue-500/30">
                <HiOutlinePlus size={18} /> Log Deposit
              </button>
            </div>
          </div>

          <div className="relative z-10 grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mt-8 pt-6 border-t border-white/20">
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10 col-span-2 lg:col-span-1">
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest flex items-center gap-1.5 mb-1"><HiOutlineShieldCheck size={14} /> Total Net Balance</p>
              <p className="text-xl sm:text-2xl font-black text-white truncate">
                {currencySymbol}{netBalance.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </p>
            </div>
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10">
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest flex items-center gap-1.5 mb-1"><HiOutlineExclamationCircle size={14} /> Global Fees Paid</p>
              <p className="text-xl sm:text-2xl font-black text-rose-300 truncate">-{currencySymbol}{totalFees.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
            </div>
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10">
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest flex items-center gap-1.5 mb-1"><FaGlobe size={12} /> Currencies</p>
              <p className="text-xl sm:text-2xl font-black text-white">{uniqueCurrenciesCount}</p>
            </div>
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10">
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest flex items-center gap-1.5 mb-1"><HiOutlineLibrary size={14} /> Entries</p>
              <p className="text-xl sm:text-2xl font-black text-white">{transactions.length}</p>
            </div>
          </div>
        </div>

        <TickerBar tickerData={tickerData} currencySymbol={currencySymbol} />

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-5">
          <StatCard title="Total Deposits" value={`${currencySymbol}${totalInflows.toLocaleString(undefined, { minimumFractionDigits: 0 })}`} icon={FaArrowDown} color="from-emerald-500 to-teal-600" subtitle="Gross money added" />
          <StatCard title="Total Withdrawn" value={`${currencySymbol}${totalOutflows.toLocaleString(undefined, { minimumFractionDigits: 0 })}`} icon={FaArrowUp} color="from-rose-500 to-pink-600" subtitle="Includes Shifts & Expenses" />
          <StatCard title="Active Banks" value={existingBanks.length} icon={FaUniversity} color="from-purple-500 to-violet-600" subtitle="Connected institutions" />
        </div>

        {subWalletBalances.length > 0 && (
          <div className="p-5 sm:p-6 bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
            <h3 className="text-xs font-black text-slate-600 dark:text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><FaUniversity className="text-blue-500" /> Bank Holdings by Currency</h3>
            <div className="flex gap-4 overflow-x-auto custom-scrollbar pb-3">
              {subWalletBalances.map((item, idx) => (<BankBadge key={idx} bank={item.bank} currency={item.currency} amount={item.value} />))}
            </div>
          </div>
        )}

        <div className="flex flex-col sm:flex-row gap-4 bg-white dark:bg-slate-900 p-4 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
          <div className="relative flex-1">
            <HiOutlineSearch className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input type="text" placeholder="Search by details, bank, or reference..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-14 pr-4 py-3.5 bg-slate-50 dark:bg-slate-800 border-2 border-slate-200 dark:border-slate-700 rounded-2xl font-bold text-slate-900 dark:text-white outline-none focus:border-blue-500 transition-all placeholder-slate-400 dark:placeholder-slate-500" />
