              <option value="out">Withdrawals/Shifts (-)</option>
            </select>
          </div>
        </div>

        {/* 🚀 COLLAPSIBLE MONTHS LEDGER */}
        {isLoading ? <LedgerSkeleton /> : processedLedger.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm px-4 animate-in zoom-in-95 duration-300">
            <div className="w-24 h-24 bg-slate-100 dark:bg-slate-800 rounded-[2rem] flex items-center justify-center mb-5 shadow-inner"><FaUniversity className="text-5xl text-slate-300 dark:text-slate-600" /></div>
            <p className="text-lg font-black text-slate-700 dark:text-slate-300">No bank records found</p>
            <p className="text-sm font-medium text-slate-500 mt-2 text-center max-w-sm">{searchTerm || filterType !== 'all' ? 'Try adjusting your search or filters.' : 'Log your first bank deposit to get started.'}</p>
            {!searchTerm && filterType === 'all' && (<button onClick={openModal} className="mt-6 bg-blue-600 hover:bg-blue-700 text-white font-black px-6 py-3 rounded-xl shadow-lg shadow-blue-500/30 transition-all active:scale-95">Log Deposit Now</button>)}
          </div>
        ) : (
          <>
            {processedLedger.map(month => {
