                      </p>
                      {(!formData.isSplit && parseFloat(formData.fee) > 0) && (
                        <p className="text-[10px] font-bold text-rose-500 dark:text-rose-400 mt-1 uppercase tracking-widest">Incl Fee: {parseFloat(formData.fee)} {formData.asset}</p>
