                              </div>
                              <div>
                                <p className="text-[10px] font-bold text-slate-400 uppercase">P/L</p>
                                <p className={`font-black flex items-center gap-1 ${isProfit ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
