                            </div>

                            <div className="flex items-center gap-2">
                              <p className="text-[9px] font-medium text-slate-400 flex items-center gap-1"><HiOutlineCalendar size={10}/> {formatGlobalDate ? formatGlobalDate(rec.date, 'short') : rec.date}</p>
