                style={{ backgroundColor: accentColor }}
              />
            </div>
          </div>
        </div>

        {/* Main value */}
        <h2 className="text-xl sm:text-2xl lg:text-3xl xl:text-4xl font-black tracking-tight text-slate-900 dark:text-white mb-2 sm:mb-3 truncate">
          {formattedValue}
