import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { HiOutlineMail, HiOutlineRefresh, HiOutlineExclamationCircle } from 'react-icons/hi';
import { sendEmailVerification } from 'firebase/auth';
import { auth } from '../firebase/firebaseConfig';

/**
 * ✅ PROTECTED ROUTE COMPONENT
 * 
 * Multi-level security gate for authenticated pages:
 * 1️⃣ Loading Check - Show spinner while verifying auth
 * 2️⃣ Login Check - Is user logged in?
 * 3️⃣ 2FA Check - Has user passed PIN verification?
 * 4️⃣ Email Verification - Is email verified?
 * 5️⃣ Access Granted - Show protected page
 * 
 * Flow: Loading → Not Logged In? → 2FA Not Passed? → Email Not Verified? → ✅ Render
 */
const ProtectedRoute = ({ children }) => {
  const { user, loading, dbData } = useAuth();
  const location = useLocation();

  // ═══════════════════════════════════════════════════════════════════════
  // 1️⃣ LOADING STATE - Show spinner while checking auth state
  // ═══════════════════════════════════════════════════════════════════════
  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-slate-50 dark:bg-slate-950">
        <div className="relative">
          <div className="w-14 h-14 border-4 border-blue-600/10 border-t-blue-600 rounded-full animate-spin" />
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-2 h-2 bg-blue-600 rounded-full animate-ping" />
          </div>
        </div>
        <p className="mt-6 text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em] animate-pulse">
          Securing Connection...
        </p>
      </div>
    );
  }

  // ═══════════════════════════════════════════════════════���═══════════════
  // 2️⃣ LOGIN CHECK - Is user logged in?
  // ═══════════════════════════════════════════════════════════════════════
  if (!user) {
    console.log('[ProtectedRoute] User not logged in, redirecting to login');
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  // ═══════════════════════════════════════════════════════════════════════
  // 3️⃣ 2FA CHECK - Has user passed PIN verification?
  // ═══════════════════════════════════════════════════════════════════════
  const isPinSet = dbData?.security?.isPinSet;
  const is2faPassed = sessionStorage.getItem('is2faPassed') === 'true';

  // If PIN is set AND user hasn't verified it yet AND not already on PIN page
  if (isPinSet && !is2faPassed && location.pathname !== '/verify-pin') {
    console.log('[ProtectedRoute] 2FA PIN required, redirecting to verify-pin');
    return <Navigate to="/verify-pin" replace />;
  }

  // ═══════════════════════════════════════════════════════════════════════
  // 4️⃣ EMAIL VERIFICATION CHECK - Is email verified?
  // ═══════════════════════════════════════════════════════════════════════
  const isSocialUser = user?.providerData?.some(
    p => p.providerId === 'google.com' || p.providerId === 'github.com'
  );

  // ✅ Social login users are auto-verified, so skip email check for them
  if (!user.emailVerified && !isSocialUser) {
    console.log('[ProtectedRoute] Email not verified, showing verification screen');

    const handleResend = async () => {
      try {
        await sendEmailVerification(user);
        alert('✅ Verification email sent! Check your inbox and spam folder.');
      } catch (error) {
        console.error('[ProtectedRoute] Resend error:', error);
        alert('❌ Failed to resend verification email. Try again later.');
      }
    };

    const handleRefresh = async () => {
      try {
        // ✅ Reload user auth state to check if email is now verified
        await user.reload();
        window.location.reload();
      } catch (error) {
        console.error('[ProtectedRoute] Refresh error:', error);
        alert('❌ Failed to refresh. Please try again.');
      }
    };

    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950 px-4">
        <div className="text-center max-w-md">
          {/* Icon */}
          <div className="w-20 h-20 bg-amber-100 dark:bg-amber-500/10 text-amber-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg">
            <HiOutlineMail size={40} />
          </div>

          {/* Title */}
          <h1 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white mb-2">
            Verify Your Email
          </h1>

          {/* Description */}
          <p className="text-slate-500 dark:text-slate-400 font-medium mb-6">
            We've sent a verification link to <br />
            <strong className="text-slate-700 dark:text-slate-200 break-all">{user.email}</strong>
            <br />
            <span className="text-xs">Please check your inbox and spam folder.</span>
          </p>

          {/* Action Buttons */}
          <div className="space-y-3">
            {/* Resend Button */}
            <button
              onClick={handleResend}
              className="w-full px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-sm transition-all active:scale-95 shadow-lg shadow-blue-500/20 flex items-center justify-center gap-2"
            >
              <HiOutlineRefresh size={18} />
              Resend Verification Email
            </button>

            {/* Already Verified Refresh Button */}
            <button
              onClick={handleRefresh}
              className="w-full px-6 py-3 bg-slate-200 dark:bg-slate-800 hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-900 dark:text-white rounded-xl font-bold text-sm transition-all active:scale-95"
            >
              Already Verified? Refresh
            </button>
          </div>

          {/* Help Text */}
          <p className="text-xs text-slate-400 mt-6 p-3 bg-slate-100 dark:bg-slate-900/50 rounded-lg flex gap-2 items-start">
            <HiOutlineExclamationCircle size={16} className="shrink-0 mt-0.5" />
            <span>
              Can't find the email? Check your spam folder, or resend a new verification link.
            </span>
          </p>
        </div>
      </div>
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  // 5️⃣ ALL CHECKS PASSED ✅ - Grant access to protected page
  // ═══════════════════════════════════════════════════════════════════════
  return children;
};

export default ProtectedRoute;

// src/utils/balanceEngine.js
//
// Balance engine for vaults and transactions.
// - Uses safeMath helpers for all numeric ops
// - Unified feeType default: 'inclusive'
// - Handles transfers, income/out, crypto types, and provides single-pass aggregator
// - Exports: calcVaultBalance, calcVaultSummary, calcAllVaultsSummary, calcAllVaultsSummarySinglePass, calcCapitalShifting, calcCapitalShiftingWithRunning

import {
  safeParseFloat,
  safeAdd,
  safeSubtract,
  safeRound,
  safeSumArr,
  safeMultiply,
} from './safeMath';

// -------------------- constants --------------------
const IN_TYPES = new Set([
  'in', 'income', 'credit',
  'buy', 'earn', 'stake_reward', 'unstake', 'bridge_in', 'swap_in', 'airdrop',
]);

const OUT_TYPES = new Set([
  'out', 'expense', 'debit',
  'sell', 'withdraw', 'stake', 'bridge_out', 'swap_out', 'fee_burn',
]);

// -------------------- helpers --------------------
function resolveDeduction(amount, fee, feeType = 'inclusive') {
  return (feeType || '').toLowerCase() === 'exclusive'
    ? safeAdd(amount, fee)
    : amount;
}

function resolveAddition(amount, fee, feeType = 'inclusive') {
  return (feeType || '').toLowerCase() === 'inclusive'
    ? safeSubtract(amount, fee)
    : amount;
}

function safeRound8(n) {
  return safeRound(n, 8);
}

function toUnixSeconds(tx) {
  // Prefer Firestore timestamp.seconds
  if (tx?.timestamp?.seconds) return Number(tx.timestamp.seconds);
  // Try ISO / date string
  if (tx?.date) {
    const parsed = Date.parse(tx.date);
    if (!Number.isNaN(parsed)) return Math.floor(parsed / 1000);
  }
  // fallback to createdAt or 0
  if (tx?.createdAt) {
    const p = Date.parse(tx.createdAt);
    if (!Number.isNaN(p)) return Math.floor(p / 1000);
  }
  return 0;
}

// -------------------- calcVaultSummary --------------------
/**
 * Full breakdown for a single vault (or global if vaultId == null)
 */
export function calcVaultSummary(transactions = [], vaultId = null) {
  const targetId = vaultId != null ? String(vaultId) : null;

  let balance = 0;
  let totalIncome = 0;
  let totalExpense = 0;
  let totalFees = 0;
  let transferIn = 0;
  let transferOut = 0;
  let txnCount = 0;

  transactions.forEach(tx => {
    // vault filter
    if (targetId) {
      const related =
        String(tx.vaultId || '') === targetId ||
        String(tx.fromVaultId || '') === targetId ||
        String(tx.toVaultId || '') === targetId;
      if (!related) return;
    }

    const rawType = (tx.type || tx.logType || '').toLowerCase();
    const fee = Math.max(0, safeParseFloat(tx.fee, 0));
    const amount = safeParseFloat(tx.finalBaseAmount ?? tx.amount, 0);
    const feeType = (tx.feeType || 'inclusive').toLowerCase();

    txnCount++;

    // transfers
    if (rawType === 'transfer' || rawType === 'capital_shift') {
      const fromId = String(tx.fromVaultId || '');
      const toId = String(tx.toVaultId || '');

      if (targetId && fromId === targetId) {
        const deduction = resolveDeduction(amount, fee, feeType);
        balance = safeSubtract(balance, deduction);
        transferOut = safeAdd(transferOut, amount);
      } else if (targetId && toId === targetId) {
        const addition = resolveAddition(amount, fee, feeType);
        balance = safeAdd(balance, addition);
        transferIn = safeAdd(transferIn, amount);
      } else if (!targetId) {
        // global view: transfers net to zero; only fees count
      }

      if (fee > 0) totalFees = safeAdd(totalFees, fee);
      return;
    }

    // income / in types
    if (IN_TYPES.has(rawType)) {
      const addition = resolveAddition(amount, fee, feeType);
      balance = safeAdd(balance, addition);
      totalIncome = safeAdd(totalIncome, amount);
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
      return;
    }

    // expense / out types
    if (OUT_TYPES.has(rawType)) {
      const deduction = resolveDeduction(amount, fee, feeType);
      balance = safeSubtract(balance, deduction);
      totalExpense = safeAdd(totalExpense, amount);
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
      return;
    }

    // unknown type: skip (or extend with custom logic)
  });

  return {
    balance: safeRound8(balance),
    totalIncome: safeRound8(totalIncome),
    totalExpense: safeRound8(totalExpense),
    totalFees: safeRound8(totalFees),
    transferIn: safeRound8(transferIn),
    transferOut: safeRound8(transferOut),
    txnCount,
  };
}

export function calcVaultBalance(transactions = [], vaultId = null) {
  const { balance, totalFees } = calcVaultSummary(transactions, vaultId);
  return { balance, totalFees };
}

// -------------------- calcAllVaultsSummary (original, simple) --------------------
/**
 * Original approach: compute per-vault by calling calcVaultSummary for each discovered vault.
 * Works fine for small datasets but O(n * v) for large ones.
 */
export function calcAllVaultsSummary(transactions = []) {
  const vaultIds = new Set();
  transactions.forEach(tx => {
    if (tx.vaultId) vaultIds.add(String(tx.vaultId));
    if (tx.fromVaultId) vaultIds.add(String(tx.fromVaultId));
    if (tx.toVaultId) vaultIds.add(String(tx.toVaultId));
  });

  const result = {};
  vaultIds.forEach(id => {
    result[id] = calcVaultSummary(transactions, id);
  });

  // compute grand totals (global)
  let totalBalance = 0;
  let totalIncome = 0;
  let totalExpense = 0;
  let totalFees = 0;

  transactions.forEach(tx => {
    const rawType = (tx.type || tx.logType || '').toLowerCase();
    if (rawType === 'transfer' || rawType === 'capital_shift') {
      const fee = Math.max(0, safeParseFloat(tx.fee, 0));
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
      return;
    }
    const amount = safeParseFloat(tx.finalBaseAmount ?? tx.amount, 0);
    const fee = Math.max(0, safeParseFloat(tx.fee, 0));
    const feeType = (tx.feeType || 'inclusive').toLowerCase();

    if (IN_TYPES.has(rawType)) {
      totalIncome = safeAdd(totalIncome, amount);
      totalBalance = safeAdd(totalBalance, resolveAddition(amount, fee, feeType));
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
    } else if (OUT_TYPES.has(rawType)) {
      totalExpense = safeAdd(totalExpense, amount);
      totalBalance = safeSubtract(totalBalance, resolveDeduction(amount, fee, feeType));
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
    }
  });

  result.total = {
    balance: safeRound8(totalBalance),
    totalIncome: safeRound8(totalIncome),
    totalExpense: safeRound8(totalExpense),
    totalFees: safeRound8(totalFees),
  };

  return result;
}

// -------------------- calcAllVaultsSummarySinglePass (recommended for large datasets) --------------------
/**
 * Single-pass aggregator: O(n) across transactions, builds per-vault summaries in one loop.
 * Recommended for large datasets.
 */
export function calcAllVaultsSummarySinglePass(transactions = []) {
  const perVault = new Map();
  let totalBalance = 0;
  let totalIncome = 0;
  let totalExpense = 0;
  let totalFees = 0;

  const ensure = (id) => {
    if (!perVault.has(id)) {
      perVault.set(id, {
        balance: 0,
        totalIncome: 0,
        totalExpense: 0,
        totalFees: 0,
      });
    }
    return perVault.get(id);
  };

  transactions.forEach(tx => {
    const rawType = (tx.type || tx.logType || '').toLowerCase();
    const fee = Math.max(0, safeParseFloat(tx.fee, 0));
    const amount = safeParseFloat(tx.finalBaseAmount ?? tx.amount, 0);
    const feeType = (tx.feeType || 'inclusive').toLowerCase();

    // transfers: update from/to vaults separately
    if (rawType === 'transfer' || rawType === 'capital_shift') {
      const from = tx.fromVaultId ? String(tx.fromVaultId) : null;
      const to = tx.toVaultId ? String(tx.toVaultId) : null;

      if (from) {
        const s = ensure(from);
        const deduction = resolveDeduction(amount, fee, feeType);
        s.balance = safeSubtract(s.balance, deduction);
        s.totalExpense = safeAdd(s.totalExpense, amount);
        s.totalFees = safeAdd(s.totalFees, fee);
      }
      if (to) {
        const s = ensure(to);
        const addition = resolveAddition(amount, fee, feeType);
        s.balance = safeAdd(s.balance, addition);
        s.totalIncome = safeAdd(s.totalIncome, amount);
        s.totalFees = safeAdd(s.totalFees, fee);
      }
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
      return;
    }

    // non-transfer: apply to tx.vaultId if present
    const vid = tx.vaultId ? String(tx.vaultId) : null;

    if (IN_TYPES.has(rawType)) {
      if (vid) {
        const s = ensure(vid);
        s.balance = safeAdd(s.balance, resolveAddition(amount, fee, feeType));
        s.totalIncome = safeAdd(s.totalIncome, amount);
        s.totalFees = safeAdd(s.totalFees, fee);
      }
      totalIncome = safeAdd(totalIncome, amount);
      totalBalance = safeAdd(totalBalance, resolveAddition(amount, fee, feeType));
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
    } else if (OUT_TYPES.has(rawType)) {
      if (vid) {
        const s = ensure(vid);
        s.balance = safeSubtract(s.balance, resolveDeduction(amount, fee, feeType));
        s.totalExpense = safeAdd(s.totalExpense, amount);
        s.totalFees = safeAdd(s.totalFees, fee);
      }
      totalExpense = safeAdd(totalExpense, amount);
      totalBalance = safeSubtract(totalBalance, resolveDeduction(amount, fee, feeType));
      if (fee > 0) totalFees = safeAdd(totalFees, fee);
    } else {
      // unknown type: skip
    }
  });

  const result = {};
  for (const [id, v] of perVault.entries()) {
    result[id] = {
      balance: safeRound8(v.balance),
      totalIncome: safeRound8(v.totalIncome),
      totalExpense: safeRound8(v.totalExpense),
      totalFees: safeRound8(v.totalFees),
    };
  }

  result.total = {
    balance: safeRound8(totalBalance),
    totalIncome: safeRound8(totalIncome),
    totalExpense: safeRound8(totalExpense),
    totalFees: safeRound8(totalFees),
  };

  return result;
}

// -------------------- calcCapitalShifting --------------------
/**
 * Returns transfer-only ledger for a vault with running balance.
 * Sorts by timestamp (oldest first). Uses toUnixSeconds for robust parsing.
 */
export function calcCapitalShifting(transactions = [], vaultId) {
  const targetId = String(vaultId);
  let runningBalance = 0;

  const shifts = transactions
    .filter(tx => {
      const rawType = (tx.type || '').toLowerCase();
      return (
        (rawType === 'transfer' || rawType === 'capital_shift') &&
        (
          String(tx.fromVaultId || '') === targetId ||
          String(tx.toVaultId || '') === targetId
        )
      );
    })
    .sort((a, b) => toUnixSeconds(a) - toUnixSeconds(b))
    .map(tx => {
      const fromId = String(tx.fromVaultId || '');
      const toId = String(tx.toVaultId || '');
      const amount = safeParseFloat(tx.finalBaseAmount ?? tx.amount, 0);
      const fee = Math.max(0, safeParseFloat(tx.fee, 0));
      const feeType = (tx.feeType || 'inclusive').toLowerCase();

      let net = 0;
      if (fromId === targetId) {
        net = -resolveDeduction(amount, fee, feeType);
      } else if (toId === targetId) {
        net = resolveAddition(amount, fee, feeType);
      }

      runningBalance = safeAdd(runningBalance, net);

      return {
        ...tx,
        netChange: safeRound8(net),
        runningBalance: safeRound8(runningBalance),
        direction: fromId === targetId ? 'out' : 'in',
      };
    });

  return { shifts, finalBalance: safeRound8(runningBalance) };
}

// -------------------- exports --------------------
export default {
  calcVaultSummary,
  calcVaultBalance,
  calcAllVaultsSummary,
  calcAllVaultsSummarySinglePass,
  calcCapitalShifting,
};

// src/utils/blogValidation.js
/**
 * Blog Data Validation Utility
 * Validates all blog fields before saving to Firestore
 * Prevents invalid data, XSS, and field length exploits
 */

const VALID_CATEGORIES = [
  "Tech & AI",
  "Crypto Strategies",
  "Wealth Management",
  "Platform Updates",
  "News"
];

const CONSTRAINTS = {
  title: { min: 5, max: 200 },
  excerpt: { min: 10, max: 500 },
  content: { min: 50, max: 50000 },
  tags: { maxCount: 10, maxLength: 50 },
  slug: { max: 300 }
};

/**
 * Validate individual blog title
 * @param {string} title - Blog title
 * @returns {Object} { valid: boolean, error?: string }
 */
export const validateTitle = (title) => {
  if (!title || typeof title !== 'string') {
    return { valid: false, error: 'Title is required' };
  }

  const trimmed = title.trim();

  if (trimmed.length < CONSTRAINTS.title.min) {
    return {
      valid: false,
      error: `Title must be at least ${CONSTRAINTS.title.min} characters`
    };
  }

  if (trimmed.length > CONSTRAINTS.title.max) {
    return {
      valid: false,
      error: `Title must be under ${CONSTRAINTS.title.max} characters (current: ${trimmed.length})`
    };
  }

  // Check for suspicious patterns
  if (/<script|javascript:|onerror|onclick/i.test(trimmed)) {
    return { valid: false, error: 'Title contains invalid characters' };
  }

  return { valid: true };
};

/**
 * Validate blog excerpt
 * @param {string} excerpt - Blog excerpt
 * @returns {Object} { valid: boolean, error?: string }
 */
export const validateExcerpt = (excerpt) => {
  if (!excerpt || typeof excerpt !== 'string') {
    return { valid: false, error: 'Excerpt is required' };
  }

  const trimmed = excerpt.trim();

  if (trimmed.length < CONSTRAINTS.excerpt.min) {
    return {
      valid: false,
      error: `Excerpt must be at least ${CONSTRAINTS.excerpt.min} characters`
    };
  }

  if (trimmed.length > CONSTRAINTS.excerpt.max) {
    return {
      valid: false,
      error: `Excerpt must be under ${CONSTRAINTS.excerpt.max} characters (current: ${trimmed.length})`
    };
  }

  return { valid: true };
};

/**
 * Validate blog category
 * @param {string} category - Blog category
 * @returns {Object} { valid: boolean, error?: string }
 */
export const validateCategory = (category) => {
  if (!category || typeof category !== 'string') {
    return { valid: false, error: 'Category is required' };
  }

  if (!VALID_CATEGORIES.includes(category)) {
    return {
      valid: false,
      error: `Invalid category. Must be one of: ${VALID_CATEGORIES.join(', ')}`
    };
  }

  return { valid: true };
};

/**
 * Validate cover image URL
 * @param {string} imageUrl - Cover image URL (optional)
 * @returns {Object} { valid: boolean, error?: string }
 */
export const validateCoverImage = (imageUrl) => {
  // Cover image is optional
  if (!imageUrl) {
    return { valid: true };
  }

  if (typeof imageUrl !== 'string') {
    return { valid: false, error: 'Cover image must be a URL string' };
  }

  const trimmed = imageUrl.trim();

  // Validate URL format
  try {
    const url = new URL(trimmed);

    // Only allow HTTPS
    if (url.protocol !== 'https:') {
      return {
        valid: false,
        error: 'Cover image must use HTTPS (secure) URL'
      };
    }

    // Check domain whitelist (optional - prevent CDN abuse)
    const allowedDomains = [
      'imgur.com',
      'imgbb.com',
      'cloudinary.com',
      'firebase.google.com',
      'github.com',
      'unsplash.com',
      'pexels.com',
      'pixabay.com'
    ];

    const hostname = url.hostname.replace('www.', '');

    // Allow any HTTPS URL for flexibility, but log suspicious ones
    console.log('[blogValidation] Image URL from domain:', hostname);

    return { valid: true };
  } catch (error) {
    return { valid: false, error: 'Cover image must be a valid HTTPS URL' };
  }
};

/**
 * Validate blog content (HTML)
 * @param {string} content - Blog HTML content
 * @returns {Object} { valid: boolean, error?: string }
 */
export const validateContent = (content) => {
  if (!content || typeof content !== 'string') {
    return { valid: false, error: 'Content is required' };
  }

  const trimmed = content.trim();

  // Check minimum length
  if (trimmed.length < CONSTRAINTS.content.min) {
    return {
      valid: false,
      error: `Content must be at least ${CONSTRAINTS.content.min} characters`
    };
  }

  // Check maximum size
  if (trimmed.length > CONSTRAINTS.content.max) {
    return {
      valid: false,
      error: `Content is too large. Must be under ${Math.round(CONSTRAINTS.content.max / 1000)}KB (current: ${Math.round(trimmed.length / 1000)}KB)`
    };
  }

  // Check if content is just empty HTML tags
  const cleanContent = trimmed
    .replace(/<[^>]+>/g, '')
    .trim();

  if (cleanContent.length < CONSTRAINTS.content.min) {
    return {
      valid: false,
      error: 'Content cannot be empty or contain only HTML tags'
    };
  }

  return { valid: true };
};

/**
 * Validate blog tags
 * @param {Array<string>} tags - Array of tags
 * @returns {Object} { valid: boolean, error?: string }
 */
export const validateTags = (tags) => {
  // Tags are optional
  if (!tags || !Array.isArray(tags) || tags.length === 0) {
    return { valid: true };
  }

  // Check tag count
  if (tags.length > CONSTRAINTS.tags.maxCount) {
    return {
      valid: false,
      error: `Maximum ${CONSTRAINTS.tags.maxCount} tags allowed (current: ${tags.length})`
    };
  }

  // Validate each tag
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];

    if (typeof tag !== 'string') {
      return {
        valid: false,
        error: `Tag ${i + 1} must be a string`
      };
    }

    const trimmedTag = tag.trim();

    if (trimmedTag.length === 0) {
      return {
        valid: false,
        error: `Tag ${i + 1} cannot be empty`
      };
    }

    if (trimmedTag.length > CONSTRAINTS.tags.maxLength) {
      return {
        valid: false,
        error: `Tag ${i + 1} must be under ${CONSTRAINTS.tags.maxLength} characters (current: ${trimmedTag.length})`
      };
    }

    // Check for suspicious characters
    if (/<script|javascript:|onerror/i.test(trimmedTag)) {
      return {
        valid: false,
        error: `Tag ${i + 1} contains invalid characters`
      };
    }
  }

  return { valid: true };
};

/**
 * Validate blog slug
 * @param {string} slug - Blog slug
 * @returns {Object} { valid: boolean, error?: string }
 */
export const validateSlug = (slug) => {
  if (!slug || typeof slug !== 'string') {
    return { valid: false, error: 'Slug is required' };
  }

  const trimmed = slug.trim();

  if (trimmed.length === 0) {
    return { valid: false, error: 'Slug cannot be empty' };
  }

  if (trimmed.length > CONSTRAINTS.slug.max) {
    return {
      valid: false,
      error: `Slug must be under ${CONSTRAINTS.slug.max} characters`
    };
  }

  // Slug should only contain lowercase letters, numbers, hyphens
  if (!/^[a-z0-9-]+$/.test(trimmed)) {
    return {
      valid: false,
      error: 'Slug must contain only lowercase letters, numbers, and hyphens'
    };
  }

  // Slug cannot start or end with hyphen
  if (trimmed.startsWith('-') || trimmed.endsWith('-')) {
    return {
      valid: false,
      error: 'Slug cannot start or end with a hyphen'
    };
  }

  return { valid: true };
};

/**
 * Complete blog data validation
 * Validates all fields and returns comprehensive error report
 * 
 * @param {Object} data - Blog data object
 * @param {string} data.title - Blog title
 * @param {string} data.excerpt - Blog excerpt
 * @param {string} data.category - Blog category
 * @param {string} data.coverImage - Cover image URL (optional)
 * @param {string} data.content - Blog HTML content
 * @param {Array<string>} data.tags - Blog tags (optional)
 * @param {string} data.slug - Blog slug (optional)
 * 
 * @returns {Object} {
 *   valid: boolean,
 *   errors: Array<string>,
 *   warnings: Array<string>
 * }
 * 
 * @example
 * const { valid, errors } = validateBlogData({
 *   title: 'My Blog Post',
 *   excerpt: 'This is a test blog post',
 *   category: 'Tech & AI',
 *   content: '<p>Full content here...</p>',
 *   coverImage: 'https://example.com/image.jpg',
 *   tags: ['react', 'javascript']
 * });
 * 
 * if (!valid) {
 *   console.error('Validation failed:', errors);
 * }
 */
export const validateBlogData = (data) => {
  const errors = [];
  const warnings = [];

  // Validate title
  const titleCheck = validateTitle(data.title);
  if (!titleCheck.valid) errors.push(titleCheck.error);

  // Validate excerpt
  const excerptCheck = validateExcerpt(data.excerpt);
  if (!excerptCheck.valid) errors.push(excerptCheck.error);

  // Validate category
  const categoryCheck = validateCategory(data.category);
  if (!categoryCheck.valid) errors.push(categoryCheck.error);

  // Validate cover image (optional)
  if (data.coverImage) {
    const imageCheck = validateCoverImage(data.coverImage);
    if (!imageCheck.valid) errors.push(imageCheck.error);
  } else {
    warnings.push('No cover image provided. Blogs look better with images.');
  }

  // Validate content
  const contentCheck = validateContent(data.content);
  if (!contentCheck.valid) errors.push(contentCheck.error);

  // Validate tags
  if (data.tags && data.tags.length > 0) {
    const tagsCheck = validateTags(data.tags);
    if (!tagsCheck.valid) errors.push(tagsCheck.error);
  }

  // Validate slug (if provided)
  if (data.slug) {
    const slugCheck = validateSlug(data.slug);
    if (!slugCheck.valid) errors.push(slugCheck.error);
  }

  // Additional security checks
  if (data.content.length > data.title.length + data.excerpt.length) {
    // Content should be substantial relative to metadata
    const ratio = data.content.length / (data.title.length + data.excerpt.length);
    if (ratio < 5) {
      warnings.push('Content seems short relative to title and excerpt.');
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
    data: {
      title: data.title?.trim() || '',
      excerpt: data.excerpt?.trim() || '',
      category: data.category || '',
      coverImage: data.coverImage?.trim() || '',
      content: data.content || '',
      tags: (data.tags || []).map(t => t.trim()).filter(t => t),
      slug: data.slug || ''
    }
  };
};

/**
 * Generate slug from title
 * @param {string} title - Blog title
 * @returns {string} Generated slug
 */
export const generateSlugFromTitle = (title) => {
  if (!title || typeof title !== 'string') return '';

  return title
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '') // Remove special characters
    .replace(/\s+/g, '-') // Replace spaces with hyphens
    .replace(/-+/g, '-') // Replace multiple hyphens with single hyphen
    .replace(/^-+|-+$/g, ''); // Remove leading/trailing hyphens
};

/**
 * Sanitize slug for safety
 * @param {string} slug - Raw slug
 * @returns {string} Sanitized slug
 */
export const sanitizeSlug = (slug) => {
  if (!slug || typeof slug !== 'string') return '';

  return slug
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9-]/g, '') // Only lowercase letters, numbers, hyphens
    .replace(/-+/g, '-') // Multiple hyphens to single
    .replace(/^-+|-+$/g, ''); // Remove leading/trailing hyphens
};

/**
 * Check if content has potential issues
 * @param {string} content - HTML content
 * @returns {Array<string>} Array of warnings
 */
export const checkContentWarnings = (content) => {
  const warnings = [];

  // Check for broken YouTube embeds
  if (content.includes('youtube.com') && !content.includes('iframe')) {
    warnings.push('YouTube links detected. Consider using embeds for better experience.');
  }

  // Check for external image count
  const externalImages = (content.match(/https?:\/\/[^\s"<>]+\.(jpg|jpeg|png|gif|webp)/gi) || []).length;
  if (externalImages > 10) {
    warnings.push(`Many external images detected (${externalImages}). May slow down loading.`);
  }

  // Check for very long paragraphs
  const paragraphs = content.match(/<p[^>]*>[\s\S]*?<\/p>/g) || [];
  const longParagraphs = paragraphs.filter(p => p.length > 1000).length;
  if (longParagraphs > 3) {
    warnings.push('Some paragraphs are very long. Consider breaking them up for readability.');
  }

  // Check for code blocks
  if (content.includes('<code') && content.length < 500) {
    warnings.push('Code block detected in short content. Make sure code is properly formatted.');
  }

  return warnings;
};

export default {
  validateTitle,
  validateExcerpt,
  validateCategory,
  validateCoverImage,
  validateContent,
  validateTags,
  validateSlug,
  validateBlogData,
  generateSlugFromTitle,
  sanitizeSlug,
  checkContentWarnings,
  VALID_CATEGORIES,
  CONSTRAINTS
};

// src/utils/encryption.js

/**
 * ✅ ENHANCED ENCRYPTION FOR SECURE NOTES
 * - v1: Legacy fixed salt (backward compatible)
 * - v2: Random per‑note salt + AES‑256‑GCM
 */

// ==================== KEY DERIVATION ====================

/**
 * Derive AES-GCM key from PIN + salt
 * @param {string} pin - User's master PIN
 * @param {Uint8Array|string} salt - Salt (16 bytes recommended)
 * @returns {Promise<CryptoKey>}
 */
export async function deriveKeyWithSalt(pin, salt) {
  const enc = new TextEncoder();
  const saltBytes = typeof salt === 'string' ? enc.encode(salt) : salt;

  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    enc.encode(pin),
    'PBKDF2',
    false,
    ['deriveKey']
  );

  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: saltBytes,
      iterations: 100000,
      hash: 'SHA-256',
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

// Legacy fixed salt key derivation (for v1 decryption only)
export async function deriveKey(pin, uid) {
  const enc = new TextEncoder();
  const salt = enc.encode('finledger-notes-' + uid);
  return deriveKeyWithSalt(pin, salt);
}

// ==================== ENCRYPTION (NEW v2) ====================

/**
 * Encrypt data with random salt (v2 format)
 * @param {string} plaintext - Note content
 * @param {string} pin - User master PIN
 * @param {string} uid - User UID (not used for v2, kept for backward compat)
 * @returns {Promise<string>} "v2:base64Salt:base64IV:base64Ciphertext"
 */
export async function encryptDataV2(plaintext, pin, uid) {
  const salt = crypto.getRandomValues(new Uint8Array(16)); // random 16 bytes
  const key = await deriveKeyWithSalt(pin, salt);
  return encryptWithKey(plaintext, key, salt);
}

async function encryptWithKey(plaintext, key, salt) {
  const enc = new TextEncoder();
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encrypted = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv },
    key,
    enc.encode(plaintext)
  );

  // Combine: salt (16) + iv (12) + ciphertext
  const combined = new Uint8Array(salt.length + iv.length + encrypted.byteLength);
  combined.set(salt, 0);
  combined.set(iv, salt.length);
  combined.set(new Uint8Array(encrypted), salt.length + iv.length);

  return 'v2:' + btoa(String.fromCharCode(...combined));
}

// ==================== DECRYPTION (v2 + legacy v1) ====================

/**
 * Decrypt data (supports v1 and v2)
 * @param {string} data - Encrypted string
 * @param {string} pin - User master PIN
 * @param {string} uid - User UID (needed for v1 only)
 * @returns {Promise<string>} - Decrypted plaintext
 */
export async function decryptDataV2(data, pin, uid) {
  if (!data || typeof data !== 'string') return '';

  // v2: random salt
  if (data.startsWith('v2:')) {
    const raw = data.slice(3);
    const bytes = Uint8Array.from(atob(raw), c => c.charCodeAt(0));

    // extract salt (first 16 bytes), iv (next 12), ciphertext (rest)
    const salt = bytes.slice(0, 16);
    const iv = bytes.slice(16, 28);
    const ciphertext = bytes.slice(28);

    const key = await deriveKeyWithSalt(pin, salt);
    const decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv },
      key,
      ciphertext
    );
    return new TextDecoder().decode(decrypted);
  }

  // v1: fixed salt (legacy)
  if (data.startsWith('v1:')) {
    const raw = data.slice(3);
    const bytes = Uint8Array.from(atob(raw), c => c.charCodeAt(0));
    const iv = bytes.slice(0, 12);
    const ciphertext = bytes.slice(12);
    const key = await deriveKey(pin, uid);
    const decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv },
      key,
      ciphertext
    );
    return new TextDecoder().decode(decrypted);
  }

  // plain old base64 (no version prefix) — migration
  try {
    return atob(data);
  } catch {
    return data; // fallback, probably plaintext already
  }
}

// ==================== LEGACY (keep for backward compat) ====================

export async function encryptData(plaintext, key) {
  // legacy wrapper, if needed anywhere
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encrypted = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv },
    key,
    new TextEncoder().encode(plaintext)
  );
  const combined = new Uint8Array(iv.length + encrypted.byteLength);
  combined.set(iv);
  combined.set(new Uint8Array(encrypted), iv.length);
  return 'v1:' + btoa(String.fromCharCode(...combined));
}

export async function decryptData(data, key) {
  // legacy wrapper, if needed
  if (data.startsWith('v1:')) {
    const raw = data.slice(3);
    const bytes = Uint8Array.from(atob(raw), c => c.charCodeAt(0));
    const iv = bytes.slice(0, 12);
    const ciphertext = bytes.slice(12);
    const decrypted = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv },
      key,
      ciphertext
    );
    return new TextDecoder().decode(decrypted);
  } else {
    try {
      return atob(data);
    } catch {
      return data;
    }
  }
}

// src/utils/errorHandler.js
export const handleAsyncError = (error, context = 'Operation') => {
  // Categorize error
  if (error.code === 'PERMISSION_DENIED') {
    return `You don't have permission to perform this ${context}`;
  }
  if (error.code === 'NETWORK_ERROR' || error.message.includes('offline')) {
    return 'Network error. Check your internet connection.';
  }
  if (error.message.includes('timeout')) {
    return `${context} timed out. Please try again.`;
  }
  return error.message || `${context} failed. Please try again.`;
};

// Usage:
try {
  await deleteDoc(...);
} catch (error) {
  const msg = handleAsyncError(error, 'Deletion');
  addToast(msg, 'error');
  console.error('Delete error:', error);
}

